#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate a headerless Cortex-M program whose functions are often first reached by a tail call.

Function i branches over an if/else (an unconditional jump to the join point), calls its successor (and sometimes
another function) directly and ends in a tail call (`return f_t(...)`, a `b.w`) to a later one. Breadth-first
discovery from the reset handler reaches most functions through a caller's tail call rounds before the direct call
to them, the shape that split functions at their internal join points.

Usage: gen-tail-calls.py COUNT SEED > out.c (build-tail-calls.sh names the fixture's values).
"""

import random
import sys


def main() -> None:
    count = int(sys.argv[1])
    rng = random.Random(int(sys.argv[2]))
    out = [
        "// SPDX-License-Identifier: Apache-2.0",
        f"// Generated by gen-tail-calls.py {count} {sys.argv[2]}; do not edit.",
        "#include <stdint.h>",
        "",
        "extern uint32_t __stack_top;",
        'volatile uint32_t sink __attribute__((section(".ram")));',
        'volatile uint32_t state[4] __attribute__((section(".ram")));',
        "",
    ]
    out += [f"uint32_t f{i}(uint32_t x);" for i in range(count)]
    out.append("")
    for i in range(count):
        # Every function is called directly by its predecessor, so its start is provable without symbols; the tail
        # call usually reaches it first, from a caller explored rounds earlier.
        later = list(range(i + 2, count))
        tail = rng.choice(later[: max(1, len(later) // 4)]) if later else None
        extra = rng.randrange(count) if rng.random() < 0.3 else None
        a, b, c, d = (rng.randrange(1, 1 << 16) for _ in range(4))
        shift = rng.randrange(1, 7)
        calls = [i + 1] if i + 1 < count else []
        calls += [extra] if extra is not None and extra != i else []
        out += [
            f"__attribute__((noinline)) uint32_t f{i}(uint32_t x) {{",
            "  uint32_t y;",
            f"  if (x & {1 << rng.randrange(0, 12)}u) {{",
            f"    y = x * {a}u + state[0];",
            f"    state[1] = y ^ {b}u;",
            "    sink = y;",
            "  } else {",
            f"    y = (x >> {shift}) ^ state[2];",
            f"    state[3] = y + {c}u;",
            "    sink = x;",
            "  }",
        ]
        out += [f"  y += f{callee}(y ^ {d}u);" for callee in calls]
        if tail is None:
            out += ["  return y;", "}", ""]
        else:
            out += [f"  return f{tail}(y + sink);", "}", ""]
    out += [
        "__attribute__((noreturn)) void default_handler(void) {",
        "  for (;;) {",
        "  }",
        "}",
        "",
        "__attribute__((noreturn)) void reset_handler(void) {",
        "  for (;;) {",
        "    sink = f0(sink);",
        "  }",
        "}",
        "",
        '__attribute__((section(".vectors"), used)) void *const vector_table[16] = {',
        "    &__stack_top, reset_handler, default_handler, default_handler, default_handler, default_handler,",
        "    default_handler, 0, 0, 0, 0, default_handler, default_handler, 0, default_handler, default_handler,",
        "};",
    ]
    print("\n".join(out))


if __name__ == "__main__":
    main()
